<?php require 'config.php'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';$s=$pdo->prepare("SELECT id,username,password FROM admins WHERE username=?");$s->execute([$u]);$a=$s->fetch();if($a&&password_verify($p,$a['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['admin_username']=$a['username'];header('Location: admin/index.php');exit;} $error='Invalid admin username/password.';}
?><!doctype html><html><head><meta charset="utf-8"><title>Admin Login</title><link rel="stylesheet" href="assets/style.css"></head><body><main><h1>Admin Login</h1><p class="error"><?=h($error)?></p><form method="post"><label>Username<input name="username" required></label><label>Password<input type="password" name="password" required></label><button>Login</button></form><p>First run <code>setup_admin.php</code> once to create the demo admin.</p></main></body></html>